// v1.15 X-P1-1: dated SEC Section 31 + FINRA TAF schedule against
// tests/golden/expected_regulatory_fees.json (generated by
// python/tools/make_golden_regulatory_fees.py), the shipped schedule file,
// and the execution simulator wiring (sell-side only, off by default).

#include <gtest/gtest.h>

#include <algorithm>
#include <cmath>
#include <vector>

#include "iap/execution/execution.hpp"
#include "iap/execution/regulatory_fees.hpp"
#include "iap/marketdata/events.hpp"
#include "iap/util/data_paths.hpp"
#include "iap/util/json.hpp"

namespace {

iap::Json golden() {
    return iap::read_json_file(iap::golden_file("expected_regulatory_fees.json"));
}

TEST(RegulatoryFees, GoldenCases) {
    const iap::Json g = golden();
    const auto sched = iap::RegulatoryFeeSchedule::from_json(g["schedule"]);
    const double tol = g["tolerance"].num();
    int n = 0;
    for (const auto& c : g["cases"].a()) {
        const double qty = static_cast<double>(c["qty"].i64());
        const double notional = qty * c["qty_unit"].num() *
                                static_cast<double>(c["price_ticks"].i64()) *
                                c["tick_size"].num();
        const auto side = static_cast<std::uint8_t>(c["side"].u64());
        const std::int64_t ts = c["ts"].i64();
        if (c.has("error")) {
            EXPECT_THROW(sched.fee(side, qty, notional, ts), std::runtime_error)
                << c["label"].s();
        } else {
            EXPECT_NEAR(sched.fee(side, qty, notional, ts), c["fee"].num(), tol)
                << c["label"].s();
        }
        ++n;
    }
    EXPECT_GE(n, 10);
}

TEST(RegulatoryFees, ShippedScheduleMatchesGoldenCopy) {
    const auto shipped = iap::RegulatoryFeeSchedule::load(
        iap::configs_dir() + "/reference/regulatory_fee_schedule.json");
    const auto copy = iap::RegulatoryFeeSchedule::from_json(golden()["schedule"]);
    ASSERT_EQ(shipped.sec.size(), copy.sec.size());
    ASSERT_EQ(shipped.taf.size(), copy.taf.size());
    for (std::size_t i = 0; i < shipped.sec.size(); ++i) {
        EXPECT_EQ(shipped.sec[i].from_ns, copy.sec[i].from_ns);
        EXPECT_EQ(shipped.sec[i].until_ns, copy.sec[i].until_ns);
        EXPECT_EQ(shipped.sec[i].rate, copy.sec[i].rate);
    }
    for (std::size_t i = 0; i < shipped.taf.size(); ++i) {
        EXPECT_EQ(shipped.taf[i].from_ns, copy.taf[i].from_ns);
        EXPECT_EQ(shipped.taf[i].until_ns, copy.taf[i].until_ns);
        EXPECT_EQ(shipped.taf[i].rate, copy.taf[i].rate);
        EXPECT_EQ(shipped.taf[i].max_per_trade, copy.taf[i].max_per_trade);
    }
}

// 2026-06-12 14:30 UTC: Section 31 $20.60/M, TAF $0.000195 capped $9.79.
constexpr std::int64_t T0 = 1781222400000000000 + 52'200'000'000'000;

iap::ExecConfig sim_config(bool with_fees) {
    iap::ExecConfig cfg;
    cfg.seed = 7;
    iap::VenueSpec v;
    v.venue_id = 1;
    v.taker_fee_per_share = 0.003;
    cfg.venues[1] = v;
    iap::InstrumentSpec ins;
    ins.instrument_id = 7;
    ins.tick_size = 0.01;
    ins.adv = 1'000'000.0;
    cfg.instruments[7] = ins;
    if (with_fees) {
        cfg.regulatory_fees = iap::RegulatoryFeeSchedule::load(
            iap::configs_dir() + "/reference/regulatory_fee_schedule.json");
    }
    return cfg;
}

iap::MarketEvent ev(std::uint64_t seq, std::int64_t ts, std::uint8_t type,
                    std::uint8_t side, std::int64_t px, std::int64_t qty) {
    return iap::MarketEvent::of(seq, 7, 1, ts, ts, seq, type, side, px, qty,
                                seq, 0);
}

std::vector<iap::Fill> run(bool with_fees, std::uint8_t side) {
    iap::ExecutionSimulator sim(sim_config(with_fees));
    sim.on_event(ev(1, T0, 1, 0, 10'000, 500));      // ADD bid
    sim.on_event(ev(2, T0 + 1, 1, 1, 10'001, 500));  // ADD ask
    iap::ChildOrder c;
    c.instrument_id = 7;
    c.venue_id = 1;
    c.side = side;
    c.type = iap::OrderType::MARKET;
    c.qty = 100;
    c.decision_ts = T0 + 10;
    sim.submit(c);
    sim.on_event(ev(3, T0 + 1'000'000'000, 9, 0, 0, 0));  // HEARTBEAT
    return sim.fills();
}

TEST(RegulatoryFees, SimulatorChargesSellsOnlyWhenEnabled) {
    const auto off = run(false, 1);
    const auto on = run(true, 1);
    ASSERT_EQ(off.size(), 1u);
    ASSERT_EQ(on.size(), 1u);
    const double notional = 100.0 * static_cast<double>(on[0].price_ticks) * 0.01;
    const double expect = 20.60 * notional / 1e6 + std::min(0.000195 * 100.0, 9.79);
    EXPECT_NEAR(on[0].fee - off[0].fee, expect, 1e-12);
    const auto buy_off = run(false, 0);
    const auto buy_on = run(true, 0);
    ASSERT_EQ(buy_on.size(), 1u);
    EXPECT_EQ(buy_on[0].fee, buy_off[0].fee);
}

}  // namespace
